// Foundry VTT Macro: Seed DR Library (сопротивления и уязвимости по типам урона)
// Заполняет компендиум "dedrel.active_effects" предметами-носителями Active Effects,
// меняющих system.dr.<тип>. Покрывает все 10 типов урона в трёх ступенях правил
// (_rules/18. Enemies.md §Уязвимости и особенности типов):
//   Слабое сопротивление  DR +2   Сильное сопротивление DR +5   Иммунитет DR +10
//   Уязвимость            DR -2   Сильная уязвимость    DR -5   Крайняя   DR -10
// Итого 60 записей. Идентификация — по system.key (effectlib_<ступень>_<тип>),
// поэтому повторный запуск не плодит дубликаты.
(async () => {
    if (!game.user.isGM) return ui.notifications.error("Макрос доступен только Мастеру.");

    const PACK_KEY = "dedrel.active_effects";
    const pack = game.packs.get(PACK_KEY);
    if (!pack) return ui.notifications.error(`Компендиум ${PACK_KEY} не найден.`);

    const ITEM_IMG = "systems/dedrel/assets/icons/items/magic_item.svg";

    // Ключи DR — из buildDR() (src/data/actors/shared-schema.mjs); подписи английские,
    // как в DR_KEY_LABELS/en.json (heat = Fire, electric = Lightning, sonic = Thunder).
    const TYPES = {
        slashing: "Slashing",
        piercing: "Piercing",
        bludgeoning: "Bludgeoning",
        heat: "Fire",
        cold: "Cold",
        necrotic: "Necrotic",
        radiant: "Radiant",
        electric: "Lightning",
        sonic: "Thunder",
        acid: "Acid"
    };

    // value — единицы DR (1 единица = 10% урона). Отрицательные = уязвимость:
    // applyDamage() трактует DR < 0 как усиление урона (src/documents/actor.mjs).
    const TIERS = [
        { slug: "weak_resist", name: (t) => `Weak resist to ${t}`, value: 2, img: "icons/svg/shield.svg" },
        { slug: "strong_resist", name: (t) => `Strong resist to ${t}`, value: 5, img: "icons/svg/mage-shield.svg" },
        { slug: "immunity", name: (t) => `Immunity to ${t}`, value: 10, img: "icons/svg/holy-shield.svg" },
        { slug: "vulnerability", name: (t) => `Vulnerability to ${t}`, value: -2, img: "icons/svg/downgrade.svg" },
        { slug: "strong_vulnerability", name: (t) => `Strong vulnerability to ${t}`, value: -5, img: "icons/svg/downgrade.svg" },
        { slug: "extreme_vulnerability", name: (t) => `Extreme vulnerability to ${t}`, value: -10, img: "icons/svg/degen.svg" }
    ];

    // Носитель: предмет magic_item с одним встроенным эффектом на system.dr.<тип>.
    // Фаза "apply" проставляется явно — хук preCreateActiveEffect не срабатывает для
    // эффектов, создаваемых вместе с родительским предметом (QUIRKS §12).
    const build = (drKey, typeLabel, tier) => {
        const name = tier.name(typeLabel);
        const pct = Math.abs(tier.value) * 10;
        const effect = tier.value > 0
            ? `снижает входящий урон типа «${typeLabel}» на ${pct}%`
            : `увеличивает входящий урон типа «${typeLabel}» на ${pct}%`;
        return {
            name,
            type: "magic_item",
            img: ITEM_IMG,
            system: {
                key: `effectlib_${tier.slug}_${drKey}`,
                description: `<p>Шаблон-носитель из библиотеки эффектов: ${effect} (<code>system.dr.${drKey}</code> ${tier.value > 0 ? "+" : ""}${tier.value}).</p>`
            },
            effects: [{
                name,
                img: tier.img,
                transfer: true,
                system: {
                    changes: [{ key: `system.dr.${drKey}`, type: "add", value: tier.value, phase: "apply" }]
                }
            }]
        };
    };

    const carriers = [];
    for (const [drKey, typeLabel] of Object.entries(TYPES)) {
        for (const tier of TIERS) carriers.push(build(drKey, typeLabel, tier));
    }

    // Существующие записи ищем по system.key: имя пользователь мог переименовать вручную.
    const docs = await pack.getDocuments();
    const byKey = new Map();
    for (const d of docs) {
        const k = d.system?.key;
        if (k) byKey.set(k, d);
    }
    const existing = carriers.filter(c => byKey.has(c.system.key));
    const missing = carriers.filter(c => !byKey.has(c.system.key));

    // Новые записи кладём в ту же папку пака, где уже лежит любая запись библиотеки DR,
    // чтобы 60 предметов не рассыпались по корню компендиума.
    const folderOf = (doc) => doc?.folder?.id ?? doc?._source?.folder ?? null;
    const defaultFolder = folderOf(existing.length ? byKey.get(existing[0].system.key) : null);

    const choice = await foundry.applications.api.DialogV2.wait({
        window: { title: "Библиотека DR: сопротивления и уязвимости" },
        content: `
            <p>Компендиум <b>${pack.title}</b>: ${TIERS.length} ступеней × ${Object.keys(TYPES).length} типов урона = <b>${carriers.length}</b> записей.</p>
            <p>Уже есть: <b>${existing.length}</b>. Нужно создать: <b>${missing.length}</b>.</p>
            <p style="color: darkorange; font-size: 0.9em;">«Пересоздать все» удалит существующие записи с теми же <code>system.key</code> вместе с их ручными правками.</p>
        `,
        buttons: [
            { action: "missing", icon: "fa-solid fa-plus", label: `Создать недостающие (${missing.length})`, default: true },
            { action: "all", icon: "fa-solid fa-rotate", label: `Пересоздать все (${carriers.length})` },
            { action: "cancel", icon: "fa-solid fa-times", label: "Отмена" }
        ],
        rejectClose: false
    });
    if (!choice || choice === "cancel") return;

    const wasLocked = pack.locked;
    if (wasLocked) await pack.configure({ locked: false });

    let created = 0;
    let deleted = 0;
    try {
        const toCreate = choice === "all" ? carriers : missing;
        for (const c of toCreate) c.folder = defaultFolder;
        if (choice === "all" && existing.length) {
            // Папку и сортировку унаследуем от удаляемой записи, чтобы структура пака не разъезжалась.
            for (const c of toCreate) {
                const old = byKey.get(c.system.key);
                if (old) {
                    c.folder = folderOf(old);
                    c.sort = old.sort;
                }
            }
            const ids = existing.map(c => byKey.get(c.system.key).id);
            await Item.deleteDocuments(ids, { pack: PACK_KEY });
            deleted = ids.length;
        }
        if (toCreate.length) {
            const res = await Item.createDocuments(toCreate, { pack: PACK_KEY });
            created = res.length;
        }
    } finally {
        if (wasLocked) await pack.configure({ locked: true });
    }

    const summary = `Библиотека DR: создано ${created}, удалено (пересоздание) ${deleted}, пропущено существующих ${choice === "all" ? 0 : existing.length}.`;
    ui.notifications.info(summary);
    console.log(`Dedrel | ${summary}`, {
        pack: PACK_KEY,
        tiers: TIERS.map(t => `${t.slug} (${t.value})`),
        types: Object.keys(TYPES)
    });
})();
